WITH reference AS (SELECT * FROM (SELECT b.mktcode,b.tgtcode,b.bizdate,b.lowPrice AS low_current,CASE WHEN COUNT(b.lowPrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 249 PRECEDING AND CURRENT ROW)=250 THEN MIN(b.lowPrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 249 PRECEDING AND CURRENT ROW) ELSE NULL END AS low_min250,CASE WHEN COUNT(b.lowPrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 249 PRECEDING AND CURRENT ROW)=250 THEN MAX(b.lowPrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 249 PRECEDING AND CURRENT ROW) ELSE NULL END AS low_max250 FROM newzl.v_hsj_stock_hq_basic b WHERE b.bizdate<='2026-04-10') w WHERE bizdate='2026-04-10'), feature AS(SELECT f.* FROM dsl_rolling_diag_2a7d2bb431c5.rolling_averages_v1 f WHERE f.bizdate='2026-04-10' AND f.snapshot_id='stock-20060104-20260414-v1' AND f.manifest_sha256='306f333e28c82c9f2c634d8a1eb64eb49d3092937d8ca7d2742d96ecdcf21a95' AND f.registry_fingerprint='6082c08809e679d4b9273b245a1c99c18bb906152313022c1bc830da36dc444d') SELECT COUNT(*) FROM reference w FULL OUTER JOIN feature f ON w.mktcode=f.mktcode AND w.tgtcode=f.tgtcode WHERE w.mktcode IS NULL OR f.mktcode IS NULL OR NOT(f.low_current <=> w.low_current) OR NOT(f.low_min250 <=> w.low_min250) OR NOT(f.low_max250 <=> w.low_max250);
